namespace sv_fff60baa43244396932dfb756b9b0c8b.Services;

public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new(
        "Jane Developer",
        "jane@example.com",
        "https://i.pravatar.cc/150?img=5",
        "Full-stack developer passionate about clean code and great UX.");

    private NotificationPrefs _notifications = new(
        true, true, false, new List<string> { "Marketing" });

    private SecuritySettings _security = new(
        true,
        DateTime.UtcNow.AddDays(-45),
        new List<ActiveSession>
        {
            new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
            new("sess-2", "Firefox on macOS", "London, UK", DateTime.UtcNow.AddHours(-3)),
            new("sess-3", "Mobile Safari", "Tokyo, JP", DateTime.UtcNow.AddDays(-1))
        });

    private AppearanceSettings _appearance = new("System", "Medium", "en", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

